'use strict';
// ITN, модули 1–4: сети сегодня, базовая настройка коммутатора и ПК, протоколы и модели, физический уровень.

lessonDef({
  id: 'itn01', topic: 'basics', minutes: 12,
  title: T('Networking Today', 'Сети сегодня', 'רשתות היום'),
  goal: T('What a network is made of, how networks are drawn, the types of networks and what makes a network reliable.',
    'Из чего состоит сеть, как её рисуют на схемах, какие бывают сети и что делает сеть надёжной.',
    'ממה מורכבת רשת, איך משרטטים אותה, אילו סוגי רשתות קיימים ומה הופך רשת לאמינה.'),
  sections: [
    lSec(['Network components', 'Компоненты сети', 'רכיבי רשת'],
      lP(['A network connects devices so they can share data. Every network has three kinds of components:',
        'Сеть соединяет устройства, чтобы они могли обмениваться данными. В любой сети есть три вида компонентов:',
        'רשת מחברת בין התקנים כדי שיוכלו לשתף מידע. בכל רשת יש שלושה סוגי רכיבים:']),
      lUL([
        ['End devices (hosts) — PCs, laptops, phones, servers, printers. They are the source or the destination of data and have an IP address.',
          'Оконечные устройства (хосты) — ПК, ноутбуки, телефоны, серверы, принтеры. Это источник или получатель данных; у них есть IP-адрес.',
          'התקני קצה (מארחים) — מחשבים, מחשבים ניידים, טלפונים, שרתים ומדפסות. הם המקור או היעד של המידע, ויש להם כתובת IP.'],
        ['Intermediary devices — switches, routers, wireless access points, firewalls. They move data between end devices and choose paths.',
          'Промежуточные устройства — коммутаторы, маршрутизаторы, точки доступа Wi-Fi, межсетевые экраны. Они передают данные между хостами и выбирают путь.',
          'התקני ביניים — מתגים, נתבים, נקודות גישה אלחוטיות וחומות אש. הם מעבירים מידע בין התקני הקצה ובוחרים את הנתיב.'],
        ['Media — copper cable, fiber-optic cable, wireless (radio). The channel the signal travels on.',
          'Среда передачи — медный кабель, оптоволокно, радиоволны. Канал, по которому идёт сигнал.',
          'מדיה — כבל נחושת, סיב אופטי, תקשורת אלחוטית (רדיו). הערוץ שבו עובר האות.'],
      ]),
      lTip(['Client-server: dedicated servers give services (web, email, files) to clients. Peer-to-peer: every computer is both client and server — cheap and simple, but no central management and weaker security.',
        'Клиент-сервер: выделенные серверы дают услуги (веб, почта, файлы) клиентам. Одноранговая сеть (peer-to-peer): каждый компьютер и клиент, и сервер — дёшево и просто, но нет централизованного управления и безопасность слабее.',
        'שרת-לקוח: שרתים ייעודיים נותנים שירותים (אתרים, דואר, קבצים) ללקוחות. עמית לעמית (peer-to-peer): כל מחשב הוא גם לקוח וגם שרת — זול ופשוט, אבל אין ניהול מרכזי והאבטחה חלשה יותר.'])),
    lSec(['Topology diagrams', 'Схемы топологии', 'שרטוטי טופולוגיה'],
      lUL([
        ['Physical topology — where devices and cables really are: rooms, racks, buildings.', 'Физическая топология — где реально стоят устройства и проходят кабели: комнаты, стойки, здания.', 'טופולוגיה פיזית — היכן נמצאים בפועל ההתקנים והכבלים: חדרים, ארונות תקשורת, בניינים.'],
        ['Logical topology — devices, ports and IP addressing: how data flows. NetTrainer\'s Logical tab is a logical topology.', 'Логическая топология — устройства, порты и IP-адреса: как идут данные. Вкладка Logical в NetTrainer — это логическая топология.', 'טופולוגיה לוגית — התקנים, פורטים ומיעון IP: איך המידע זורם. לשונית Logical ב-NetTrainer היא טופולוגיה לוגית.'],
        ['NIC — network interface card in a host. Port / interface — a connector on a network device.', 'NIC — сетевая карта хоста. Порт / интерфейс — разъём на сетевом устройстве.', 'NIC — כרטיס רשת במחשב. פורט / ממשק — חיבור בהתקן רשת.'],
      ])),
    lSec(['Types of networks', 'Виды сетей', 'סוגי רשתות'],
      lTable([['Type', 'Вид', 'סוג'], ['What it is', 'Что это', 'מה זה']], [
        ['LAN', ['Local network in one building or campus, run by one organization. Fast, usually Ethernet and Wi-Fi.', 'Локальная сеть в одном здании или кампусе, одна организация. Быстрая, обычно Ethernet и Wi-Fi.', 'רשת מקומית בבניין או בקמפוס אחד, בניהול ארגון אחד. מהירה, בדרך כלל Ethernet ו-Wi-Fi.']],
        ['WAN', ['Connects LANs over long distances, often through a service provider.', 'Соединяет LAN на больших расстояниях, обычно через провайдера.', 'מחברת רשתות LAN למרחקים גדולים, בדרך כלל דרך ספק שירות.']],
        ['Internet', ['A worldwide network of networks. Nobody owns it as a whole.', 'Всемирная «сеть сетей». Целиком никому не принадлежит.', 'רשת עולמית של רשתות. אף אחד אינו הבעלים של כולה.']],
        ['Intranet', ['A private network for the people of one organization only.', 'Частная сеть только для сотрудников одной организации.', 'רשת פרטית רק לאנשי ארגון אחד.']],
        ['Extranet', ['Secure access to part of an organization\'s network for outside partners and suppliers.', 'Защищённый доступ к части сети организации для внешних партнёров и поставщиков.', 'גישה מאובטחת לחלק מרשת הארגון עבור שותפים וספקים חיצוניים.']],
      ]),
      lP(['Home Internet connections: cable, DSL, cellular, satellite. Businesses also use dedicated leased lines and Metro Ethernet. A converged network carries data, voice and video over the same infrastructure.',
        'Домашний интернет: кабельный, DSL, сотовый, спутниковый. Компании также используют выделенные линии и Metro Ethernet. Конвергентная сеть передаёт данные, голос и видео по одной инфраструктуре.',
        'חיבורי אינטרנט ביתיים: כבלים, DSL, סלולרי, לוויין. עסקים משתמשים גם בקווים ייעודיים וב-Metro Ethernet. רשת מתכנסת (converged) מעבירה נתונים, קול ווידאו על אותה תשתית.'])),
    lSec(['Reliable networks', 'Надёжная сеть', 'רשת אמינה'],
      lP(['A reliable network has four basic characteristics:', 'У надёжной сети четыре базовых свойства:', 'לרשת אמינה ארבעה מאפיינים בסיסיים:']),
      lUL([
        ['Fault tolerance — redundant paths, so one failure does not stop the network.', 'Отказоустойчивость — резервные пути, чтобы один отказ не остановил сеть.', 'עמידות בתקלות — נתיבים חלופיים, כך שתקלה אחת לא עוצרת את הרשת.'],
        ['Scalability — the network can grow without a redesign.', 'Масштабируемость — сеть может расти без перепроектирования.', 'יכולת הרחבה (scalability) — הרשת יכולה לגדול בלי תכנון מחדש.'],
        ['Quality of Service (QoS) — priority for time-sensitive traffic such as voice and video.', 'Качество обслуживания (QoS) — приоритет для трафика, чувствительного к задержке: голос и видео.', 'איכות שירות (QoS) — עדיפות לתעבורה רגישה לזמן, כמו קול ווידאו.'],
        ['Security — confidentiality, integrity and availability (the CIA triad).', 'Безопасность — конфиденциальность, целостность и доступность (триада CIA).', 'אבטחה — סודיות, שלמות וזמינות (משולש CIA).'],
      ]),
      lTip(['Interview tip: "What makes a network reliable?" — name these four and give one example for each.',
        'Совет к собеседованию: «Что делает сеть надёжной?» — назовите эти четыре свойства и приведите по примеру на каждое.',
        'טיפ לראיון: "מה הופך רשת לאמינה?" — מנו את ארבעת המאפיינים ותנו דוגמה לכל אחד.'])),
    lSec(['Trends and security', 'Тенденции и безопасность', 'מגמות ואבטחה'],
      lUL([
        ['BYOD — people bring their own devices to work.', 'BYOD — сотрудники приносят свои устройства на работу.', 'BYOD — עובדים מביאים לעבודה את ההתקנים שלהם.'],
        ['Cloud computing — public, private, hybrid and community clouds.', 'Облачные вычисления — публичное, частное, гибридное и общественное облако.', 'מחשוב ענן — ענן ציבורי, פרטי, היברידי וקהילתי.'],
        ['Online collaboration and video communication.', 'Онлайн-совместная работа и видеосвязь.', 'שיתוף פעולה מקוון ותקשורת וידאו.'],
      ]),
      lP(['Common threats: viruses, worms and Trojan horses, spyware, zero-day attacks, denial of service (DoS), data interception and identity theft. Home networks use antivirus and a firewall; companies add dedicated firewalls, access lists (ACL), intrusion prevention (IPS) and VPNs.',
        'Частые угрозы: вирусы, черви и трояны, шпионские программы, атаки нулевого дня, отказ в обслуживании (DoS), перехват данных и кража личности. Дома защищаются антивирусом и межсетевым экраном; компании добавляют выделенные межсетевые экраны, списки доступа (ACL), системы предотвращения вторжений (IPS) и VPN.',
        'איומים נפוצים: וירוסים, תולעים וסוסים טרויאניים, תוכנות ריגול, מתקפות יום אפס, מניעת שירות (DoS), יירוט מידע וגניבת זהות. בבית מתגוננים באנטי-וירוס ובחומת אש; ארגונים מוסיפים חומות אש ייעודיות, רשימות גישה (ACL), מערכות למניעת חדירות (IPS) ו-VPN.'])),
  ],
  quiz: [
    lQ(['Which of these is an intermediary device?', 'Какое из этих устройств промежуточное?', 'איזה מההתקנים הבאים הוא התקן ביניים?'],
      [['Switch', 'Коммутатор', 'מתג'], ['Laptop', 'Ноутбук', 'מחשב נייד'], ['Printer', 'Принтер', 'מדפסת'], ['Server', 'Сервер', 'שרת']], 0,
      ['Switches, routers and access points move data between end devices.', 'Коммутаторы, маршрутизаторы и точки доступа передают данные между оконечными устройствами.', 'מתגים, נתבים ונקודות גישה מעבירים מידע בין התקני קצה.']),
    lQ(['What is a host?', 'Что такое хост?', 'מהו מארח (host)?'],
      [['An end device that sends or receives data and has an IP address', 'Оконечное устройство, которое отправляет или получает данные и имеет IP-адрес', 'התקן קצה ששולח או מקבל מידע ויש לו כתובת IP'], ['Any switch', 'Любой коммутатор', 'כל מתג'], ['A network cable', 'Сетевой кабель', 'כבל רשת'], ['The Internet provider', 'Интернет-провайдер', 'ספק האינטרנט']], 0,
      ['Hosts are the source or destination of messages: PCs, servers, phones, printers.', 'Хосты — источник или получатель сообщений: ПК, серверы, телефоны, принтеры.', 'מארחים הם המקור או היעד של ההודעות: מחשבים, שרתים, טלפונים, מדפסות.']),
    lQ(['Which network is limited to one building or campus and run by one organization?', 'Какая сеть ограничена одним зданием или кампусом и управляется одной организацией?', 'איזו רשת מוגבלת לבניין או לקמפוס אחד ומנוהלת בידי ארגון אחד?'],
      ['LAN', 'WAN', 'Internet', 'Extranet'], 0,
      ['LAN = local area network. A WAN connects LANs over long distances.', 'LAN — локальная сеть. WAN соединяет LAN на больших расстояниях.', 'LAN היא רשת מקומית. WAN מחברת רשתות LAN למרחקים גדולים.']),
    lQ(['Which diagram shows IP addresses and interface names?', 'На какой схеме видны IP-адреса и имена интерфейсов?', 'באיזה שרטוט רואים כתובות IP ושמות ממשקים?'],
      [['Logical topology', 'Логическая топология', 'טופולוגיה לוגית'], ['Physical topology', 'Физическая топология', 'טופולוגיה פיזית'], ['Floor plan', 'План этажа', 'תוכנית קומה'], ['Rack diagram', 'Схема стойки', 'שרטוט ארון תקשורת']], 0,
      ['The logical topology shows devices, ports and addressing; the physical one shows real locations.', 'Логическая топология показывает устройства, порты и адресацию; физическая — реальное расположение.', 'הטופולוגיה הלוגית מציגה התקנים, פורטים ומיעון; הפיזית מציגה מיקום בפועל.']),
    lQ(['Which four characteristics make a network reliable?', 'Какие четыре свойства делают сеть надёжной?', 'אילו ארבעה מאפיינים הופכים רשת לאמינה?'],
      [['Fault tolerance, scalability, QoS, security', 'Отказоустойчивость, масштабируемость, QoS, безопасность', 'עמידות בתקלות, יכולת הרחבה, QoS, אבטחה'], ['Speed, price, size, color', 'Скорость, цена, размер, цвет', 'מהירות, מחיר, גודל, צבע'], ['Hubs, switches, routers, cables', 'Хабы, коммутаторы, маршрутизаторы, кабели', 'רכזות, מתגים, נתבים, כבלים'], ['LAN, WAN, intranet, extranet', 'LAN, WAN, интранет, экстранет', 'LAN, WAN, אינטראנט, אקסטראנט']], 0,
      ['These are the four basic characteristics of network architecture.', 'Это четыре базовых свойства сетевой архитектуры.', 'אלה ארבעת המאפיינים הבסיסיים של ארכיטקטורת רשת.']),
    lQ(['What does QoS do?', 'Что делает QoS?', 'מה עושה QoS?'],
      [['Gives priority to time-sensitive traffic like voice and video', 'Даёт приоритет трафику, чувствительному к задержке: голос и видео', 'נותן עדיפות לתעבורה רגישה לזמן כמו קול ווידאו'], ['Encrypts the traffic', 'Шифрует трафик', 'מצפין את התעבורה'], ['Adds redundant links', 'Добавляет резервные каналы', 'מוסיף קווים חלופיים'], ['Assigns IP addresses', 'Назначает IP-адреса', 'מקצה כתובות IP']], 0,
      ['Quality of Service manages congestion so a phone call does not break up when a big download runs.', 'QoS управляет перегрузкой, чтобы звонок не прерывался во время большой загрузки.', 'QoS מנהל עומסים כדי ששיחת טלפון לא תיקטע כשמתבצעת הורדה גדולה.']),
    lQ(['What is an extranet?', 'Что такое экстранет?', 'מהו אקסטראנט?'],
      [['Secure access to an organization\'s network for outside partners', 'Защищённый доступ к сети организации для внешних партнёров', 'גישה מאובטחת לרשת הארגון עבור שותפים חיצוניים'], ['The public Internet', 'Публичный интернет', 'האינטרנט הציבורי'], ['A home Wi-Fi network', 'Домашняя Wi-Fi-сеть', 'רשת Wi-Fi ביתית'], ['A network for employees only', 'Сеть только для сотрудников', 'רשת לעובדים בלבד']], 0,
      ['A network only for employees is an intranet.', 'Сеть только для сотрудников — это интранет.', 'רשת לעובדים בלבד היא אינטראנט.']),
    lQ(['What is a disadvantage of a peer-to-peer network?', 'Какой недостаток у одноранговой сети?', 'מהו חיסרון של רשת עמית לעמית?'],
      [['No central administration and weaker security', 'Нет централизованного управления, безопасность слабее', 'אין ניהול מרכזי והאבטחה חלשה יותר'], ['It needs expensive dedicated servers', 'Нужны дорогие выделенные серверы', 'צריך שרתים ייעודיים יקרים'], ['Computers cannot share files', 'Компьютеры не могут обмениваться файлами', 'מחשבים לא יכולים לשתף קבצים'], ['It only works over fiber', 'Работает только по оптоволокну', 'עובדת רק על סיב אופטי']], 0,
      ['P2P is cheap and easy, but it does not scale and is hard to secure.', 'P2P дёшево и просто, но плохо масштабируется и её трудно защитить.', 'P2P זולה ופשוטה, אבל לא מתרחבת היטב וקשה לאבטח אותה.']),
    lQ(['A network that keeps working when one link fails is…', 'Сеть, которая продолжает работать при отказе одного канала, — это…', 'רשת שממשיכה לעבוד כשקו אחד נופל היא…'],
      [['Fault tolerant', 'отказоустойчивая', 'עמידה בתקלות'], ['Scalable', 'масштабируемая', 'ניתנת להרחבה'], ['Converged', 'конвергентная', 'מתכנסת'], ['Peer-to-peer', 'одноранговая', 'עמית לעמית']], 0,
      ['Redundant paths give fault tolerance.', 'Резервные пути дают отказоустойчивость.', 'נתיבים חלופיים מעניקים עמידות בתקלות.']),
  ],
});

