lessonDef({
  id: 'itn02', topic: 'device', minutes: 15,
  title: T('Basic Switch and End Device Configuration', 'Базовая настройка коммутатора и оконечных устройств', 'הגדרה בסיסית של מתג והתקני קצה'),
  goal: T('How to reach the CLI, the IOS modes, basic commands, passwords, saving the configuration and IP settings on a switch and a PC.',
    'Как попасть в CLI, режимы IOS, базовые команды, пароли, сохранение конфигурации и IP-настройки коммутатора и ПК.',
    'איך מגיעים ל-CLI, מצבי IOS, פקודות בסיסיות, סיסמאות, שמירת התצורה והגדרות IP במתג ובמחשב.'),
  sections: [
    lSec(['Accessing Cisco IOS', 'Доступ к Cisco IOS', 'גישה ל-Cisco IOS'],
      lUL([
        ['Console — a cable to the console port. Works without any network configuration (out-of-band).', 'Console — кабель в консольный порт. Работает без сетевых настроек (внеполосный доступ).', 'Console — כבל לפורט הקונסולה. עובד בלי שום הגדרת רשת (out-of-band).'],
        ['SSH — encrypted remote access over the network. Recommended.', 'SSH — зашифрованный удалённый доступ по сети. Рекомендуется.', 'SSH — גישה מרחוק מוצפנת דרך הרשת. מומלץ.'],
        ['Telnet — remote access in clear text. Not secure.', 'Telnet — удалённый доступ открытым текстом. Небезопасно.', 'Telnet — גישה מרחוק בטקסט גלוי. לא מאובטח.'],
      ]),
      lP(['Terminal programs: PuTTY, Tera Term, SecureCRT. In NetTrainer: PC → Desktop → Terminal (console cable) or the CLI tab of the device.',
        'Терминальные программы: PuTTY, Tera Term, SecureCRT. В NetTrainer: ПК → Desktop → Terminal (консольный кабель) или вкладка CLI устройства.',
        'תוכנות טרמינל: PuTTY, Tera Term, SecureCRT. ב-NetTrainer: מחשב → Desktop → Terminal (כבל קונסולה) או לשונית CLI של ההתקן.'])),
    lSec(['IOS modes', 'Режимы IOS', 'מצבי IOS'],
      lTable([['Prompt', 'Приглашение', 'סמן'], ['Mode', 'Режим', 'מצב'], ['How to enter', 'Как войти', 'איך נכנסים']], [
        ['Switch>', ['User EXEC — only basic show and ping', 'Пользовательский EXEC — только базовые show и ping', 'User EXEC — רק show ו-ping בסיסיים'], ['after login', 'после входа', 'אחרי כניסה']],
        ['Switch#', ['Privileged EXEC — all show, copy, reload', 'Привилегированный EXEC — все show, copy, reload', 'Privileged EXEC — כל פקודות show, copy, reload'], 'enable'],
        ['Switch(config)#', ['Global configuration', 'Глобальная конфигурация', 'תצורה גלובלית'], 'configure terminal'],
        ['Switch(config-if)#', ['Interface configuration', 'Настройка интерфейса', 'הגדרת ממשק'], 'interface fa0/1'],
        ['Switch(config-line)#', ['Line configuration', 'Настройка линий', 'הגדרת קווים'], 'line console 0 / line vty 0 15'],
      ]),
      lUL([
        ['exit — one level back. end or Ctrl+Z — straight back to privileged EXEC.', 'exit — на уровень назад. end или Ctrl+Z — сразу в привилегированный EXEC.', 'exit — רמה אחת אחורה. end או Ctrl+Z — ישר חזרה ל-privileged EXEC.'],
        ['? — help, Tab — complete the word, ↑ — command history. Commands can be shortened: conf t, sh ip int br.', '? — подсказка, Tab — дописать слово, ↑ — история команд. Команды можно сокращать: conf t, sh ip int br.', '? — עזרה, Tab — השלמת מילה, ↑ — היסטוריית פקודות. אפשר לקצר פקודות: conf t, sh ip int br.'],
        ['do <command> — run an EXEC command from config mode, e.g. do show ip interface brief.', 'do <команда> — выполнить EXEC-команду из режима конфигурации, например do show ip interface brief.', 'do <פקודה> — הרצת פקודת EXEC מתוך מצב תצורה, למשל do show ip interface brief.'],
      ])),
    lSec(['Basic device configuration', 'Базовая настройка устройства', 'הגדרה בסיסית של התקן'],
      lCode('Switch> enable\nSwitch# configure terminal\nSwitch(config)# hostname S1\nS1(config)# enable secret class\nS1(config)# line console 0\nS1(config-line)# password cisco\nS1(config-line)# login\nS1(config-line)# exit\nS1(config)# line vty 0 15\nS1(config-line)# password cisco\nS1(config-line)# login\nS1(config-line)# exit\nS1(config)# service password-encryption\nS1(config)# banner motd #Authorized access only!#'),
      lUL([
        ['hostname — a unique name; it appears in the prompt.', 'hostname — уникальное имя; оно появляется в приглашении.', 'hostname — שם ייחודי; הוא מופיע בסמן.'],
        ['enable secret — protects privileged mode, stored as a hash. Prefer it to enable password.', 'enable secret — защищает привилегированный режим, хранится как хеш. Лучше, чем enable password.', 'enable secret — מגן על המצב המורשה ונשמר כגיבוב (hash). עדיף על enable password.'],
        ['line console 0 / line vty — passwords for console and remote access; "login" turns the check on.', 'line console 0 / line vty — пароли на консоль и удалённый доступ; «login» включает проверку.', 'line console 0 / line vty — סיסמאות לקונסולה ולגישה מרחוק; "login" מפעיל את הבדיקה.'],
        ['service password-encryption — hides plain-text passwords in the config (weak type 7).', 'service password-encryption — скрывает открытые пароли в конфиге (слабый type 7).', 'service password-encryption — מסתיר סיסמאות גלויות בתצורה (הצפנה חלשה, type 7).'],
        ['banner motd — a warning shown before login.', 'banner motd — предупреждение перед входом.', 'banner motd — הודעת אזהרה לפני הכניסה.'],
      ])),
    lSec(['Saving the configuration', 'Сохранение конфигурации', 'שמירת התצורה'],
      lP(['Commands change the running-config in RAM at once — it is lost after a reboot. The startup-config in NVRAM is loaded at boot.',
        'Команды сразу меняют running-config в оперативной памяти — после перезагрузки он теряется. При загрузке читается startup-config из NVRAM.',
        'פקודות משנות מיד את ה-running-config בזיכרון RAM — והוא אובד אחרי אתחול. בזמן עלייה נטען ה-startup-config מ-NVRAM.']),
      lCode('S1# copy running-config startup-config\nS1# show running-config\nS1# show startup-config\nS1# erase startup-config      ! back to factory settings after reload\nS1# reload'),
      lTip(['Made a mistake and have not saved yet? "reload" without saving brings back the last saved configuration.',
        'Ошиблись и ещё не сохранили? «reload» без сохранения вернёт последнюю сохранённую конфигурацию.',
        'טעיתם ועוד לא שמרתם? "reload" בלי שמירה מחזיר את התצורה האחרונה שנשמרה.'])),
    lSec(['IP addresses on a switch and a PC', 'IP-адреса на коммутаторе и ПК', 'כתובות IP במתג ובמחשב'],
      lP(['A PC needs an IP address, subnet mask, default gateway and DNS server — typed manually or received from DHCP. A Layer 2 switch gets an IP only for management, on the virtual interface VLAN 1 (SVI).',
        'ПК нужны IP-адрес, маска, шлюз по умолчанию и DNS-сервер — вручную или от DHCP. Коммутатор 2-го уровня получает IP только для управления — на виртуальном интерфейсе VLAN 1 (SVI).',
        'מחשב צריך כתובת IP, מסכת רשת, שער ברירת מחדל ושרת DNS — ידנית או מ-DHCP. מתג שכבה 2 מקבל כתובת IP רק לניהול, בממשק הווירטואלי VLAN 1 (SVI).']),
      lCode('S1(config)# interface vlan 1\nS1(config-if)# ip address 192.168.1.2 255.255.255.0\nS1(config-if)# no shutdown\nS1(config-if)# exit\nS1(config)# ip default-gateway 192.168.1.1'),
      lUL([
        ['PC: Desktop → IP Configuration (Static or DHCP). Check with ipconfig.', 'ПК: Desktop → IP Configuration (Static или DHCP). Проверка — ipconfig.', 'מחשב: Desktop → IP Configuration (סטטי או DHCP). בדיקה עם ipconfig.'],
        ['Switch: show ip interface brief. Test: ping from the PC to the switch IP.', 'Коммутатор: show ip interface brief. Проверка: ping с ПК на IP коммутатора.', 'מתג: show ip interface brief. בדיקה: ping מהמחשב לכתובת ה-IP של המתג.'],
      ])),
  ],
  quiz: [
    lQ(['The prompt is "S1(config-if)#". Which mode is this?', 'Приглашение «S1(config-if)#». Какой это режим?', 'הסמן הוא "S1(config-if)#". באיזה מצב אנחנו?'],
      [['Interface configuration', 'Настройка интерфейса', 'הגדרת ממשק'], ['Global configuration', 'Глобальная конфигурация', 'תצורה גלובלית'], ['Privileged EXEC', 'Привилегированный EXEC', 'Privileged EXEC'], ['Line configuration', 'Настройка линий', 'הגדרת קווים']], 0,
      ['(config-if) = interface, (config) = global, # alone = privileged EXEC.', '(config-if) — интерфейс, (config) — глобальный, просто # — привилегированный EXEC.', '(config-if) = ממשק, (config) = גלובלי, # לבד = privileged EXEC.']),
    lQ(['Which command takes you from "S1>" to "S1#"?', 'Какая команда переводит из «S1>» в «S1#»?', 'איזו פקודה מעבירה מ-"S1>" ל-"S1#"?'],
      ['enable', 'configure terminal', 'login', 'exit'], 0,
      ['enable enters privileged EXEC. configure terminal works only from "#".', 'enable — вход в привилегированный режим. configure terminal работает только из «#».', 'enable נכנס ל-privileged EXEC. configure terminal עובד רק מ-"#".']),
    lQ(['Which access method works even when the device has no IP configuration?', 'Какой способ доступа работает, даже если у устройства нет IP-настроек?', 'איזו שיטת גישה עובדת גם כשאין להתקן הגדרות IP?'],
      ['Console', 'SSH', 'Telnet', 'HTTP'], 0,
      ['Console is out-of-band: a direct cable to the device.', 'Консоль — внеполосный доступ: прямой кабель к устройству.', 'הקונסולה היא גישה out-of-band: כבל ישיר להתקן.']),
    lQ(['How does "enable secret" differ from "enable password"?', 'Чем «enable secret» отличается от «enable password»?', 'במה שונה "enable secret" מ-"enable password"?'],
      [['It is stored as a hash and takes precedence', 'Хранится как хеш и имеет приоритет', 'נשמר כגיבוב (hash) וגובר על השני'], ['It is weaker', 'Он слабее', 'הוא חלש יותר'], ['There is no difference', 'Ничем', 'אין הבדל'], ['It only protects the console', 'Защищает только консоль', 'מגן רק על הקונסולה']], 0,
      ['If both are configured, the router asks for the secret.', 'Если заданы оба, устройство спросит secret.', 'אם שניהם מוגדרים, ההתקן מבקש את ה-secret.']),
    lQ(['How do you keep the configuration after a reboot?', 'Как сохранить конфигурацию после перезагрузки?', 'איך שומרים את התצורה אחרי אתחול?'],
      ['copy running-config startup-config', 'copy startup-config running-config', 'save config', 'reload'], 0,
      ['running-config is in RAM; startup-config in NVRAM is loaded at boot.', 'running-config — в RAM; при загрузке читается startup-config из NVRAM.', 'ה-running-config ב-RAM; ה-startup-config ב-NVRAM נטען בזמן העלייה.']),
    lQ(['Where do you configure the management IP address of a Layer 2 switch?', 'Где задаётся IP-адрес для управления коммутатором 2-го уровня?', 'היכן מגדירים כתובת IP לניהול במתג שכבה 2?'],
      [['On interface vlan 1 (SVI)', 'На interface vlan 1 (SVI)', 'בממשק vlan 1 (SVI)'], ['On interface fa0/1', 'На interface fa0/1', 'בממשק fa0/1'], ['On line console 0', 'На line console 0', 'ב-line console 0'], ['A switch cannot have an IP', 'У коммутатора не бывает IP', 'למתג לא יכולה להיות כתובת IP']], 0,
      ['The SVI is a virtual interface; physical switch ports do not take IP addresses.', 'SVI — виртуальный интерфейс; физическим портам коммутатора IP не назначают.', 'SVI הוא ממשק וירטואלי; לפורטים פיזיים של מתג לא מגדירים כתובת IP.']),
    lQ(['Which lines are used for Telnet and SSH?', 'Какие линии используются для Telnet и SSH?', 'אילו קווים משמשים ל-Telnet ול-SSH?'],
      ['line vty', 'line console 0', 'line aux 0', 'interface vlan 1'], 0,
      ['vty = virtual terminal lines for remote access.', 'vty — виртуальные терминальные линии для удалённого доступа.', 'vty הם קווי טרמינל וירטואליים לגישה מרחוק.']),
    lQ(['What does the "end" command do?', 'Что делает команда «end»?', 'מה עושה הפקודה "end"?'],
      [['Returns straight to privileged EXEC', 'Возвращает сразу в привилегированный EXEC', 'חוזרת ישר ל-privileged EXEC'], ['Logs out of the CLI', 'Завершает сеанс CLI', 'מתנתקת מה-CLI'], ['Saves the configuration', 'Сохраняет конфигурацию', 'שומרת את התצורה'], ['Goes back one level', 'Возвращает на уровень назад', 'חוזרת רמה אחת']], 0,
      ['end = Ctrl+Z. exit goes back one level.', 'end — то же, что Ctrl+Z. exit — на уровень назад.', 'end זהה ל-Ctrl+Z. exit חוזר רמה אחת.']),
    lQ(['What does "service password-encryption" do?', 'Что делает «service password-encryption»?', 'מה עושה "service password-encryption"?'],
      [['Hides plain-text passwords in the configuration (weak encryption)', 'Скрывает открытые пароли в конфигурации (слабое шифрование)', 'מסתיר סיסמאות גלויות בתצורה (הצפנה חלשה)'], ['Enables SSH', 'Включает SSH', 'מפעיל SSH'], ['Encrypts all network traffic', 'Шифрует весь трафик', 'מצפין את כל התעבורה'], ['Replaces enable secret', 'Заменяет enable secret', 'מחליף את enable secret']], 0,
      ['It only protects passwords from someone reading the config.', 'Она только прячет пароли от того, кто читает конфиг.', 'היא רק מסתירה סיסמאות ממי שקורא את התצורה.']),
  ],
});

